// Read-only TapeOut integration. No wallet, signer, transaction or local fallback.
export const CIRCUIT=Object.freeze({chainId:196,rpc:'https://rpc.xlayer.tech',address:'0x4f3b708af365b8f339dd35a8985ffe06c2553400',id:48,tapeId:'48.2.167',processor:167,author:'0x1839231f7fc0d55a3ec58736574aca13f711326d'});
const word=n=>BigInt(n).toString(16).padStart(64,'0');
// keccak256 signatures, independently checked against mainnet.
const selectors={eval:'934d06ea',info:'084d60f1',owner:'6352211e',netlist:'3fc4be56'};
export function evalData(a,b){if(![a,b].every(n=>n===0||n===1))throw Error('Invalid input bits');return '0x'+selectors.eval+word(48)+word(64)+word(1)+(a|(b<<1)).toString(16).padStart(2,'0')+'00'.repeat(31);}
export function decodeBytes(hex){if(typeof hex!=='string'||!/^0x[0-9a-f]*$/i.test(hex)||hex.length<130)throw Error('Malformed ABI bytes');const raw=hex.slice(2),offset=Number(BigInt('0x'+raw.slice(0,64)))*2;if(offset!==64)throw Error('Unexpected ABI offset');const size=Number(BigInt('0x'+raw.slice(offset,offset+64)));if(!Number.isSafeInteger(size)||size<0||raw.length<offset+64+size*2)throw Error('Truncated ABI bytes');return '0x'+raw.slice(offset+64,offset+64+size*2);}
export async function rpc(method,params=[],fetcher=fetch){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetcher(CIRCUIT.rpc,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:controller.signal});if(!response.ok)throw Error('RPC HTTP '+response.status);const value=await response.json();if(value.error||value.result===undefined)throw Error(value.error?.message||'Missing RPC result');return value.result;}finally{clearTimeout(timer);}}
async function read(data,block,fetcher){return rpc('eth_call',[{to:CIRCUIT.address,data},block],fetcher);}
export async function evaluateGate(a,b,{fetcher=fetch,block}={}){block??=await rpc('eth_blockNumber',[],fetcher);if(!/^0x[0-9a-f]+$/i.test(block))throw Error('Invalid block');const data=evalData(a,b),raw=await read(data,block,fetcher),output=decodeBytes(raw);if(!['0x00','0x01'].includes(output))throw Error('Unexpected circuit output');const OUT0=Number(output==='0x01');if(OUT0!==(a&&b?0:1))throw Error('Circuit logic changed');return {IN0:a,IN1:b,OUT0,chainId:196,contract:CIRCUIT.address,circuitId:48,blockNumber:parseInt(block,16),blockTag:block,method:'eth_call',calldata:data,rawResult:raw,checkedAt:new Date().toISOString()};}
export async function verifyCircuit(fetcher=fetch){const chain=await rpc('eth_chainId',[],fetcher);if(chain!=='0xc4')throw Error('Wrong network');const block=await rpc('eth_blockNumber',[],fetcher),id=word(48);
 const [info,owner,rawNetlist]=await Promise.all([read('0x'+selectors.info+id,block,fetcher),read('0x'+selectors.owner+id,block,fetcher),read('0x'+selectors.netlist+id,block,fetcher)]),netlist=decodeBytes(rawNetlist);
 if(!/^0x[0-9a-f]{256}$/i.test(info))throw Error('Invalid circuit metadata');const shape=info.slice(2).match(/.{64}/g).map(x=>Number(BigInt('0x'+x)));if(shape.join(',')!=='2,1,0,3')throw Error('Circuit shape changed');if(!/^0x[0-9a-f]{64}$/i.test(owner)||'0x'+owner.slice(-40).toLowerCase()!==CIRCUIT.author)throw Error('Circuit owner changed');
 const cases=await Promise.all([[0,0],[0,1],[1,0],[1,1]].map(([a,b])=>evaluateGate(a,b,{fetcher,block})));return {schema:'money-lab.tapeout-proof.v1',...CIRCUIT,blockNumber:parseInt(block,16),owner:CIRCUIT.author,shape,netlist,cases,checkedAt:new Date().toISOString()};}
